            canvas.width = width;
            canvas.height = height;
            const newContext = canvas.getContext('2d');
            if (!newContext) {
                return Promise.resolve(undefined);
            }
            newContext.putImageData(newImage, 0, 0);

            return Promise.resolve(canvas);
