            atlas.render(renderer, this._averageLabel, avgRight - atlas.measure(this._averageLabel), baseline, 0, MUTED);
            if (this._showPeak) atlas.render(renderer, 'Peak', right - atlas.measure('Peak'), baseline, 0, MUTED);
