static set(a, b, type) {
        const len  = a.length;

        if (type === 'quaternion') {
            let l = AnimBlend.dot(b, b);
            if (l > 0) {
                l = 1.0 / Math.sqrt(l);
            }
            for (let i = 0; i < len; ++i) {
                a[i] = b[i] * l;
            }
        } else {
            for (let i = 0; i < len; ++i) {
                a[i] = b[i];
            }
        }
    }

static blend(a, b, t, type, additive) {
        if (type === 'quaternion') {
            AnimBlend.blendQuat(a, b, t, additive);
        } else {
            AnimBlend.blendVec(a, b, t, additive);
        }
    }

static stableSort(a, lessFunc) {
        const len = a.length;
        for (let i = 0; i < len - 1; ++i) {
            for (let j = i + 1; j < len; ++j) {
                if (lessFunc(a[j], a[i])) {
                    const tmp = a[i];
                    a[i] = a[j];
                    a[j] = tmp;
                }
            }
        }
    }

