/**
 * Warn once if the current page is not a secure context. Fires on any
 * insecure origin; browsers treat localhost / 127.0.0.1 / ::1 as secure
 * even over http, so those won't trigger it. No-ops outside the browser
 * and when `window.isSecureContext` is not explicitly `false` (older or
 * embedded runtimes may leave it undefined).
 *
 * @param {string} feature - Feature name (e.g. 'WebGPU', 'WebXR').
 * @ignore
 */
(feature) => {
    if (typeof window === 'undefined') return;
    if (window.isSecureContext !== false) return;
    Debug.warnOnce(
        `${feature} requires a secure context (HTTPS or localhost). ` +
        `The page is served over an insecure origin; ${feature} will be unavailable.`
    );
}

/**
     * @param {string} type - Session type.
     * @param {string} spaceType - Reference space type.
     * @param {*} options - Session options.
     * @param {XrErrorCallback} callback - Error callback.
     * @private
     */
_onStartOptionsReady(type, spaceType, options, callback) {
        // only a rejected request is handled here, as once granted, _onSessionStart ends a session
        // that fails to start
        navigator.xr.requestSession(type, options).then((session) => {
            this._onSessionStart(session, spaceType, callback);
        }, (ex) => {
            this._onStartFailed(ex, callback);
        });
    }

/**
     * @param {number} near - Near plane distance.
     * @param {number} far - Far plane distance.
     * @private
     */
_setClipPlanes(near, far) {
        if (this._depthNear === near && this._depthFar === far) {
            return;
        }

        this._depthNear = near;
        this._depthFar = far;

        if (!this._session) {
            return;
        }

        // if session is available,
        // queue up render state update
        this._session.updateRenderState({
            depthNear: this._depthNear,
            depthFar: this._depthFar
        });
    }

