finalize(device, shader) {

        // if the device is lost, silently ignore
        const gl = device.gl;
        if (gl.isContextLost()) {
            return true;
        }

        const glProgram = this.glProgram;
        const definition = shader.definition;

        // #if _PROFILER
        const startTime = now();
        device.fire('shader:link:start', {
            timestamp: startTime,
            target: device
        });
        // #endif

        // this is the main thead blocking part of the shader compilation, time it
        let linkStartTime = 0;
        Debug.call(() => {
            linkStartTime = now();
        });

        // check the link status of a shader - this is a blocking operation waiting for the shader
        // to finish compiling and linking
        const linkStatus = gl.getProgramParameter(glProgram, gl.LINK_STATUS);
        if (!linkStatus) {

            // Check for compilation errors (use the actually-compiled sources so line numbers match)
            if (!this._isCompiled(device, shader, this.glVertexShader, this._vsource, 'vertex')) {
                return false;
            }

            if (!this._isCompiled(device, shader, this.glFragmentShader, this._fsource, 'fragment')) {
                return false;
            }

            const message = `Failed to link shader program. Error: ${gl.getProgramInfoLog(glProgram)}`;

            // #if _DEBUG

            // log translated shaders
            definition.translatedFrag = gl.getExtension('WEBGL_debug_shaders')?.getTranslatedShaderSource(this.glFragmentShader);
            definition.translatedVert = gl.getExtension('WEBGL_debug_shaders')?.getTranslatedShaderSource(this.glVertexShader);

            console.error(message, definition);
            // #else
            console.error(message);
            // #endif

            return false;
        }

        // Query the program for each vertex buffer input (GLSL 'attribute')
        const numAttributes = gl.getProgramParameter(glProgram, gl.ACTIVE_ATTRIBUTES);
        shader.attributes.clear();
        for (let i = 0; i < numAttributes; i++) {
            const info = gl.getActiveAttrib(glProgram, i);
            const location = gl.getAttribLocation(glProgram, info.name);

            // a built-in attributes for which we do not need to provide any data
            if (_vertexShaderBuiltins.has(info.name)) {
                continue;
            }

            // Check attributes are correctly linked up
            if (definition.attributes[info.name] === undefined) {
                console.error(`Vertex shader attribute "${info.name}" is not mapped to a semantic in shader definition, shader [${shader.label}]`, shader);
                shader.failed = true;
            } else {
                shader.attributes.set(location, info.name);
            }
        }

        // Query the program for each shader state (GLSL 'uniform')
        const samplerTypes = device._samplerTypes;
        const numUniforms = gl.getProgramParameter(glProgram, gl.ACTIVE_UNIFORMS);
        for (let i = 0; i < numUniforms; i++) {
            const info = gl.getActiveUniform(glProgram, i);
            const location = gl.getUniformLocation(glProgram, info.name);

            // a built-in variables reported as uniforms for which we do not need to provide any data
            if (_vertexShaderBuiltins.has(info.name)) {
                continue;
            }

            // uniforms that are members of a uniform block have no individual location - they are
            // supplied through a bound uniform buffer, so skip them from the per-uniform commit path
            if (location === null) {
                continue;
            }

            const shaderInput = new WebglShaderInput(device, info.name, device.pcUniformType[info.type], location);

            if (samplerTypes.has(info.type)) {
                this.samplers.push(shaderInput);
            } else {
                this.uniforms.push(shaderInput);
            }
        }

        // Link uniform blocks to their binding points. By convention a block is named
        // 'ub_<bindGroupName>' (e.g. 'ub_view', 'ub_mesh_ub') and is bound to the matching bind
        // group index, which is used as its GL uniform buffer binding point (see
        // WebglGraphicsDevice.setBindGroup). A block not following this convention cannot be
        // matched to a binding point - it is asserted in debug builds and ignored otherwise.
        const numBlocks = gl.getProgramParameter(glProgram, gl.ACTIVE_UNIFORM_BLOCKS);
        for (let i = 0; i < numBlocks; i++) {
            const blockName = gl.getActiveUniformBlockName(glProgram, i);
            const shortName = blockName.startsWith('ub_') ? blockName.substring(3) : blockName;
            const bindGroupIndex = bindGroupNames.indexOf(shortName);

            Debug.assert(bindGroupIndex >= 0,
                `Shader [${shader.label}] declares an unsupported uniform block [${blockName}] - user uniform buffers are not supported.`,
                shader);

            const bindingPoint = bindGroupIndex >= 0 ? bindGroupIndex : i;
            gl.uniformBlockBinding(glProgram, i, bindingPoint);
        }

        shader.ready = true;

        // #if _PROFILER
        const endTime = now();
        device.fire('shader:link:end', {
            timestamp: endTime,
            target: device
        });
        device._shaderStats.compileTime += endTime - startTime;
        // #endif

        Debug.call(() => {
            const duration = now() - linkStartTime;
            this.compileDuration += duration;
            _totalCompileTime += this.compileDuration;
            Debug.trace(TRACEID_SHADER_COMPILE, `[id: ${shader.id}] ${shader.name}: ${this.compileDuration.toFixed(1)}ms, TOTAL: ${_totalCompileTime.toFixed(1)}ms`);
        });

        return true;
    }

