        // update stats
        this.renderer._gsplatCount = gsplatCount;
        this.renderer._gsplatBufferCopy = bufferCopyTotal > 0 ?
            (bufferCopyUploaded / bufferCopyTotal * 100) : 0;

        // clear dirty flags
        this.gsplat.frameEnd();

        tempDirtyLayers.clear();
