     * Create a new UniformBuffer instance.
     *
     * @param {GraphicsDevice} graphicsDevice - The graphics device used to manage this uniform
     * buffer.
     * @param {UniformBufferFormat} format - Format of the uniform buffer.
     * @param {boolean} [persistent] - Whether the buffer is persistent. Defaults to true.
     */
constructor(graphicsDevice, format, persistent = true) {
        this.device = graphicsDevice;
        this.format = format;
        this.persistent = persistent;
        Debug.assert(format);

        if (persistent) {

            this.impl = graphicsDevice.createUniformBufferImpl(this);

            const storage = new ArrayBuffer(format.byteSize);
            this.assignStorage(new Int32Array(storage));

            graphicsDevice._vram.ub += this.format.byteSize;

            // register with the device so the GPU buffer is recreated and re-uploaded on a lost
            // context (non-persistent buffers re-allocate from the dynamic buffers on next update)
            this.device.buffers.add(this);
        } else {

            this.allocation = new DynamicBufferAllocation();
        }
    }

/**
     * Splits the parameters between the scope and the material uniform buffer again, after the
     * material or its set of typed properties changed.
     *
     * @private
     */
_rebuildParameterLists() {
        this._scopeParameters.length = 0;
        this._materialOverrides.length = 0;
        this._materialTextureOverrides.length = 0;
        for (const parameter of this.parameters.values()) {
            this._addParameter(parameter);
        }
        this._materialLayoutVersion = this._material?.layoutVersion ?? -1;
        this._materialOverridesVersion++;
    }

/**
     * Releases the per-instance copy of the material uniform buffer.
     *
     * @private
     */
_destroyMaterialUniformBuffer() {
        this._materialBindGroup?.destroy();
        this._materialBindGroup = null;
        this._materialUniformBuffer?.destroy();
        this._materialUniformBuffer = null;
    }

