calcSpawnPosition(particleTex, spawnMatrix, extentsInnerRatioUniform, emitterPos, i) {
        const emitter = this._emitter;

        const rX = Math.random();
        const rY = Math.random();
        const rZ = Math.random();
        const rW = Math.random();
